'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var bench = require( '@stdlib/bench' );
var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var Float32Array = require( '@stdlib/array/float32' );
var tryRequire = require( '@stdlib/utils/try-require' );
var pkg = require( './../package.json' ).name;


// VARIABLES //

var srotmg = tryRequire(resolve(__dirname, './../lib/assign.native.js'));
var opts = {
	'skip': (srotmg instanceof Error)
};
var options = {
	'dtype': 'float32'
};


// MAIN //

bench( pkg+':assign::native', opts, function benchmark( b ) {
	var out;
	var d1;
	var d2;
	var x1;
	var y1;
	var z;
	var i;

	d1 = discreteUniform( 100, -5, 5, options );
	d2 = discreteUniform( 100, -5, 5, options );
	x1 = discreteUniform( 100, -5, 5, options );
	y1 = discreteUniform( 100, -5, 5, options );
	out = new Float32Array( 5 );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		z = srotmg( d1[ i%d1.length ], d2[ i%d2.length ], x1[ i%x1.length ], y1[ i%y1.length ], out, 1, 0 );
		if ( typeof z !=='object' ) {
			b.fail( 'should return an array' );
		}
	}
	b.toc();
	if ( isnanf( z[ i%5 ] ) ) {
		b.fail( 'should return the output array' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
